/*
 * prog40_bisection_root
 *
 * Re‑implemented from the observed behaviour of the supplied binary.
 * The program reads a single integer argument N and computes an
 * approximation of sqrt(N) using a fixed‑iteration bisection method.
 *
 * Behaviour:
 *   - If no argument is supplied:          prints "NO_INPUT"
 *   - If the argument is not a valid integer
 *     (or contains extra characters):    prints "BAD_INPUT"
 *   - If the integer is negative:         prints "BAD_INPUT"
 *   - If the integer is greater than 1 000 000: prints "OUT_OF_RANGE"
 *   - Otherwise prints an approximation of sqrt(N) with
 *     six digits after the decimal point.
 *
 * The algorithm performs up to 60 bisection steps, which is enough
 * to reach the required 1e‑6 precision for the allowed range.
 */

#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv)
{
    /* ----- error handling ----- */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    /* not a number or extra characters after the number */
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }

    if (n > 1000000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ----- bisection square‑root ----- */
    double low  = 0.0;
    double high = (double)n;   /* the original binary added a constant that is 0.0 */
    double mid  = 0.0;
    int   iter = 0;

    while (iter < 60) {
        mid = (high - low) * 0.5 + low;   /* _DAT_00102008 is 0.5 */
        if ((double)n < mid * mid) {
            high = mid;
        } else {
            low = mid;
        }
        ++iter;
    }

    printf("%.6f\n", mid);
    return 0;
}
